import Link from 'next/link'
import { notFound } from 'next/navigation'
import type { Metadata } from 'next'

type BlogPostParams = Promise<{ id: string }>

export const dynamicParams = true

export async function generateStaticParams() {
  const posts: { id: number }[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({
  params,
}: {
  params: BlogPostParams
}): Promise<Metadata> {
  const { id } = await params
  try {
    const post: { title: string; body: string } = await fetch(
      `https://jsonplaceholder.typicode.com/posts/${id}`
    ).then((res) => res.json())

    return {
      title: `${post.title} - My Blog`,
      description: post.body.substring(0, 160),
      openGraph: {
        title: post.title,
        description: post.body.substring(0, 160),
      },
    }
  } catch {
    return { title: 'Post Not Found' }
  }
}

async function getPost(id: string) {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
    next: { revalidate: 300 },
  })
  if (!res.ok) return null
  return res.json()
}

async function getComments(id: string) {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } }
  )
  if (!res.ok) return []
  return res.json()
}

export default async function BlogPost({
  params,
}: {
  params: BlogPostParams
}) {
  const { id } = await params

  const [post, comments] = await Promise.all([
    getPost(id),
    getComments(id),
  ])

  if (!post) {
    notFound()
  }

  return (
    <article>
      <Link href="/blog">&larr; Back</Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment: { id: number; name: string; body: string; email: string }) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

